class Solution:
    def removeOuterParentheses(self, s: str) -> str:
        c=0
        res=''
        for i in s:
            if i==')' and c==1:
                c=c-1
            elif i=='(' and c==0:
                c=c+1
            elif i=='(':
                res=res+'('
                c=c+1
            elif i==')':
                res=res+')'
                c=c-1
        return res

class Solution:
    def removeDuplicates(self, S: str) -> str:
        stack = []
        for char in S:
            if stack and stack[-1] == char:
                stack.pop()
            else:
                stack.append(char)

        return ''.join(stack)

